const placeholderContract:Partial<Record<InventoryTranslationKey,readonly string[]>>={
  sourceFetchedExpires:["provider","fetched","expires"],
  seatCount:["count"],
  stars:["count"],
  remainingSeats:["count"],
};

function restorePlaceholders(key:InventoryTranslationKey,value:string):string{
  const expected=placeholderContract[key];
  if(!expected)return value;
  const placeholders=value.match(/\{[^}]+\}/g)??[];
  if(placeholders.length!==expected.length){
    return rawInventoryTranslations.en[key];
  }
  let index=0;
  return value.replace(/\{[^}]+\}/g,()=>`{${expected[Math.min(index++,expected.length-1)]}}`);
}

export const inventoryTranslations=Object.fromEntries(
  Object.entries(rawInventoryTranslations).map(([locale,catalog])=>[
    locale,
    Object.fromEntries(
      Object.entries(catalog).map(([key,value])=>[
        key,
        restorePlaceholders(key as InventoryTranslationKey,value),
      ]),
    ),
  ]),
) as Record<Locale,Record<InventoryTranslationKey,string>>;
